def solve(rows):
    state = 5
    kept = []
    for i, row in enumerate(rows):
        if type(row) is int:
            weight = row
        elif isinstance(row, str):
            weight = int(row.split('|')[1])
        else:
            weight = sum((v for v in row if type(v) is int)) + sum((len(v) for v in row if isinstance(v, str)))
        if (state + weight + i) % 7 != 2 or i == len(rows) - 1:
            kept.append(row)
        state = 5 if weight == 0 else (3 * state + weight) % 7
