    state = 5
    kept_rows = []
    allocations = []
    remaining_budget = 15

    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            try:
                weight = int(row[1:-1])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        keep = (state + weight + i) % 7 != 2 or i == len(rows) - 1
        if keep:
            kept_rows.append(row)

        if weight == 0:
            state = 5
        else:
            state = (3 * state + weight) % 7

    if kept_rows:
        final_state = state
        kept_length = len(kept_rows)
        rotation_amount = final_state % kept_length
        rotated_kept_rows = kept_rows[rotation_amount:] + kept_rows[:rotation_amount]

        for row in rotated_kept_rows:
            if isinstance(row, list) and len(row) == 2 and isinstance(row[0], int) and isinstance(row[1], int):
                capacity = row[0]
                request = row[1]
                allocation = min(capacity, request, remaining_budget)
                allocations.append(allocation)
                remaining_budget -= allocation

    return allocations

